def open_days(due, returned, closed=(6,), holidays=()):
    count = 0
    day = due + timedelta(days=1)
    while day <= returned:
        if day.weekday() not in closed and day not in holidays:
            count += 1
        day += timedelta(days=1)
    return count


def charged_days(days_open):
    return max(0, days_open - GRACE_DAYS)


